/// <summary>
/// The version provider delivers the version number used in the application configuration file.
/// </summary>
/// <returns></returns>
public static str getCurrentVersion()
{
    TFMVersionProvider versionProvider = new TFMVersionProvider();
    return versionProvider.getBaseVersionID() + '_' + TFMDocLocalization::getUserLanguage() + '_' + versionProvider.getProviderVersions();  
}

public str getBaseVersionID()
{
    System.Collections.IDictionary appWideDictionary = this.inMemoryDictionary();
    str verIdStr = this.getBaseVersionStrKey();
    if(!appWideDictionary.Contains(verIdStr))
    {
        appWideDictionary.set_Item(verIdStr, this.getBaseVersionValue());
    }
    return appWideDictionary.get_Item(verIdStr);
}

	public static void reset()
    {
        new TFMVersionProvider().resetBaseVersion();
    }

	public void resetBaseVersion()
    {
        System.Collections.IDictionary appWideDictionary = this.inMemoryDictionary();
        str verIdStr = this.getBaseVersionStrKey();
        appWideDictionary.set_Item(verIdStr, this.getBaseVersionValue());
    }

protected str getBaseVersionStrKey()
{
    return resourceStr(TaskletFactory) + strLwr(curExt());
}

protected str getBaseVersionValue()
{
    return strKeep(System.String::Format('{0:s}', DateTimeUtil::utcNow()),'1234567890') + strLwr(curExt());
}

public str getProviderVersions()
{
    SetEnumerator   providerClasses = TFMProvider::getProviders(true).getEnumerator(); //only receive the once that has an instance method so if a provider needs to contribute it most have an instance method.
    str             providerVersions;
    TFMProvider     provider;
    str             pVersion;

    while (providerClasses.moveNext())
    {
        provider = providerClasses.current();
        pVersion = provider.version();
        if(pVersion)
        {
            providerVersions += '.' + pVersion;
        }
    }

    return providerVersions;
}
